package fr.xerion.xrnhud;
import java.nio.file.*;import java.util.*;import com.google.gson.*;import net.minecraft.resources.Identifier;import net.minecraft.client.Minecraft;import com.mojang.blaze3d.platform.NativeImage;import net.minecraft.client.renderer.texture.DynamicTexture;
/** Local rendering cache only. Other players' Prime rights always come from the verified relay. */
public final class PrimeClient {
 private static String uuid="";private static long verifiedUntil,lastRead,lastOutfit;private static int tier;private static boolean launched;private static final Map<String,String> hashes=new HashMap<>();
 private record Loaded(Identifier texture,String sha){}private static final Map<String,Long> used=new HashMap<>(),retry=new HashMap<>();private static final LinkedHashMap<String,Loaded> textures=new LinkedHashMap<>(32,.75f,true);
 private PrimeClient(){}
 public static void rafraichir(){if(!Boolean.getBoolean("XRNPrimeEnabled"))return;long now=System.currentTimeMillis();if(now-lastRead<1500)return;lastRead=now;hashes.clear();verifiedUntil=0;uuid="";tier=0;
  Droits.CATALOGUE.removeIf(c->c.id.matches("prime_[a-f0-9]{32}"));
  try{String file=System.getProperty("XRNPrime","");if(file.isEmpty()||Files.size(Path.of(file))>262144)return;JsonObject o=JsonParser.parseString(Files.readString(Path.of(file))).getAsJsonObject();launched=o.has("launched")&&o.get("launched").getAsBoolean();uuid=o.get("uuid").getAsString();if(!uuid.matches("[a-f0-9]{32}"))return;verifiedUntil=o.get("active").getAsBoolean()?Math.min(o.get("until").getAsLong(),o.get("verifiedUntil").getAsLong()):0;
   if(verifiedUntil<=now)return;tier=o.has("tier")?Math.max(0,Math.min(4,o.get("tier").getAsInt())):0;if(o.has("outfit")&&o.get("outfit").isJsonObject()){var outfit=o.getAsJsonObject("outfit");long revision=outfit.get("revision").getAsLong();if(revision!=lastOutfit&&uuid.equals(outfit.get("uuid").getAsString())){var st=outfit.getAsJsonObject("style");NameTag.actif=st.get("enabled").getAsBoolean();NameTag.badge=st.get("badge").getAsBoolean();NameTag.gradient=st.get("gradient").getAsBoolean();NameTag.anime=st.get("animate").getAsBoolean();NameTag.arcenciel=st.get("rainbow").getAsBoolean();NameTag.debut=st.get("start").getAsInt()|0xff000000;NameTag.fin=st.get("end").getAsInt()|0xff000000;lastOutfit=revision;}}
   for(JsonElement value:o.getAsJsonArray("capes")){JsonObject c=value.getAsJsonObject();String id=c.get("id").getAsString(),sha=c.get("sha256").getAsString();if(!id.matches("prime_[a-f0-9]{32}")||!sha.matches("[a-f0-9]{64}"))continue;String name=c.get("name").getAsString();if(name.length()>40)continue;hashes.put(id,sha);Droits.CATALOGUE.add(new Droits.Cosmetique(id,name,"cape",0,"#B9A0EE",false));}
  }catch(RuntimeException|java.io.IOException ignored){}
 }
 public static boolean actif(java.util.UUID player){if(!Boolean.getBoolean("XRNPrimeEnabled"))return false;rafraichir();if(player==null)return false;return player.toString().replace("-","").equals(uuid)&&verifiedUntil>System.currentTimeMillis()||Connus.prime(player);}
 public static int niveau(java.util.UUID player){if(!actif(player))return 0;return player.toString().replace("-","").equals(uuid)?tier:Connus.niveauPrime(player);}
 public static boolean peutAnimer(){if(!Boolean.getBoolean("XRNPrimeEnabled"))return false;var c=Minecraft.getInstance();return c.player!=null&&actif(c.player.getUUID());}
 public static Identifier texture(String id){if(id==null||!id.matches("prime_[a-f0-9]{32}"))return null;rafraichir();String sha=hashes.getOrDefault(id,Connus.hashCape(id));if(sha==null)return null;Loaded old=textures.get(id);if(old!=null&&old.sha.equals(sha)){used.put(id,System.currentTimeMillis());return old.texture;}if(retry.getOrDefault(id,0L)>System.currentTimeMillis())return null;if(old==null&&textures.size()>=64){var first=textures.entrySet().iterator().next();if(used.getOrDefault(first.getKey(),0L)>System.currentTimeMillis()-2000)return null;}
  try{String root=System.getProperty("XRNPrimeCapes","");if(root.isEmpty())return null;Path file=Path.of(root).resolve(id+".png");if(Files.size(file)>524288)return null;byte[] png=Files.readAllBytes(file);if(png.length<33||java.nio.ByteBuffer.wrap(png).getInt(16)!=1024||java.nio.ByteBuffer.wrap(png).getInt(20)!=512)return null;String digest=HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(png));if(!digest.equals(sha))return null;NativeImage image=NativeImage.read(png);if(image.getWidth()!=1024||image.getHeight()!=512){image.close();return null;}var manager=Minecraft.getInstance().getTextureManager();Identifier texture=Identifier.fromNamespaceAndPath("xrnhud","prime/"+id);manager.register(texture,new DynamicTexture(()->"XRN personal cape",image));textures.put(id,new Loaded(texture,sha));used.put(id,System.currentTimeMillis());while(textures.size()>64){String first=textures.keySet().iterator().next();used.remove(first);manager.release(textures.remove(first).texture);}return texture;
  }catch(Exception ignored){retry.put(id,System.currentTimeMillis()+2000);return null;}
 }
 public static void noterProches(){try{String target=System.getProperty("XRNVisiblePlayers","");if(target.isEmpty())return;var c=Minecraft.getInstance();var ids=new JsonArray();if(c.level!=null){int n=0;for(var player:c.level.players()){if(++n>256)break;ids.add(player.getUUID().toString().replace("-",""));}}var value=new JsonObject();value.add("uuids",ids);value.addProperty("updatedAt",System.currentTimeMillis());Path file=Path.of(target),temp=file.resolveSibling(file.getFileName()+".tmp");Files.createDirectories(file.getParent());Files.writeString(temp,value.toString());Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING);}catch(Exception ignored){}}
}
